class LRUCache {
    class DLinkedNode{
        int key;
        int val;
        DLinkedNode pre;
        DLinkedNode next;
        DLinkedNode(){}
        DLinkedNode(int key, int val){
            this.key = key;
            this.val = val;
        }
    }
    DLinkedNode head;
    DLinkedNode tail;
    int size = 0;
    int capacity;
    Map<Integer,DLinkedNode> cache = new HashMap<>();
    public LRUCache(int capacity) {
        this.capacity = capacity;
        head = new DLinkedNode();
        tail = new DLinkedNode();
        head.next = tail;
        tail.pre = head;
    }
    public int get(int key) {
        DLinkedNode node = cache.get(key);
        if(node==null){
            return -1;
        }else{
            removeNode(node);
            addToHead(node);
            return node.val;
        }
    }
    public void put(int key, int value) {
        DLinkedNode node = cache.get(key);
        if(node==null){
            size++;
            if(size>capacity){
                size--;
                cache.remove(tail.pre.key);
                removeNode(tail.pre);
            }
            node = new DLinkedNode(key,value);
            addToHead(node);
            cache.put(key,node);
        }else{
            node.val = value;
            removeNode(node);
            addToHead(node);
        }
    }
    public void removeNode(DLinkedNode node){
        node.pre.next = node.next;
        node.next.pre = node.pre;
    }
    public void addToHead(DLinkedNode node){
        node.next = head.next;
        node.next.pre = node;
        node.pre = head;
        head.next = node;
    }
}
